using Windows.Win32;
using Windows.Win32.System.Com;
using Windows.Win32.UI.Shell;

namespace WinApps.Services.Packages;

// Native Shell interfaces generated by CsWin32; no WScript, dynamic binding,
// runtime COM wrappers, or runtime code generation.
internal sealed unsafe class ShellShortcut : IDisposable
{
    private IShellLinkW* _link;
    private IPersistFile* _file;
    private readonly bool _uninitialize;
    internal ShellShortcut(string? path = null)
    {
        var initialized = PInvoke.CoInitializeEx(null, COINIT.COINIT_APARTMENTTHREADED);
        _uninitialize = initialized.Value >= 0;
        if (!_uninitialize && initialized.Value != unchecked((int)0x80010106)) initialized.ThrowOnFailure();
        try
        {
            var classId = new Guid("00021401-0000-0000-C000-000000000046");
            var linkId = IShellLinkW.IID_Guid;
            void* instance;
            PInvoke.CoCreateInstance(&classId, null, CLSCTX.CLSCTX_INPROC_SERVER, &linkId, &instance).ThrowOnFailure();
            _link = (IShellLinkW*)instance;
            var persistId = IPersistFile.IID_Guid;
            _link->QueryInterface(&persistId, &instance).ThrowOnFailure();
            _file = (IPersistFile*)instance;
            if (path is not null) _file->Load(path, STGM.STGM_READ);
        }
        catch { Dispose(); throw; }
    }
    internal string TargetPath { get => Read(0); set => _link->SetPath(value); }
    internal string Arguments { get => Read(1); set => _link->SetArguments(value); }
    internal string WorkingDirectory { get => Read(2); set => _link->SetWorkingDirectory(value); }
    internal string Description { set => _link->SetDescription(value); }
    internal string IconLocation
    {
        get => Read(3);
        set
        {
            var comma = value.LastIndexOf(',');
            if (comma >= 0 && int.TryParse(value[(comma + 1)..], out var index)) _link->SetIconLocation(value[..comma], index);
            else _link->SetIconLocation(value, 0);
        }
    }
    private string Read(int property)
    {
        Span<char> buffer = stackalloc char[32768];
        buffer.Clear();
        var index = 0;
        if (property == 0) { fixed (char* text = buffer) _link->GetPath(text, buffer.Length, null, 4); }
        else if (property == 1) _link->GetArguments(buffer);
        else if (property == 2) _link->GetWorkingDirectory(buffer);
        else _link->GetIconLocation(buffer, out index);
        var end = buffer.IndexOf('\0');
        var value = buffer[..(end < 0 ? buffer.Length : end)].ToString();
        return property == 3 && value.Length > 0 ? $"{value},{index}" : value;
    }
    internal void Save(string path) => _file->Save(path, true);
    public void Dispose()
    {
        if (_file is not null) { _file->Release(); _file = null; }
        if (_link is not null) { _link->Release(); _link = null; }
        if (_uninitialize && !_disposed) PInvoke.CoUninitialize();
        _disposed = true;
    }
    private bool _disposed;
}
